import (
	"testing"

	"github.com/debricked/cli/internal/sanitize/pm/util"
	"github.com/stretchr/testify/assert"
)

// #nosec G101 -- fake credentials, the test checks they are removed
const installJSONBefore = `{
    "dependency_tree": {
        "__AUTOGENERATED_FILE_DO_NOT_MODIFY_THIS_FILE_MANUALLY": 1234,
        "__INPUT_ARTIFACTS_HASH": 5678,
        "conflict_resolution": {},
        "dependencies": [
            {
                "coord": "com.acme:auth-client:2.1.0",
                "dependencies": [
                    "com.google.guava:guava:32.0.0-jre",
                    "com.google.code.findbugs:jsr305:3.0.2"
                ],
                "directDependencies": [
                    "com.google.guava:guava:32.0.0-jre"
                ],
                "file": "v1/https/artifactory.acme.internal/libs/com/acme/auth-client-2.1.0.jar",
                "mirror_urls": [
                    "https://ci-user:s3cret@artifactory.acme.internal/libs/com/acme/auth-client-2.1.0.jar"
                ],
                "sha256": "aaaa",
                "url": "https://ci-user:s3cret@artifactory.acme.internal/libs/com/acme/auth-client-2.1.0.jar"
            },
            {
                "coord": "com.google.guava:guava:32.0.0-jre",
                "dependencies": [
                    "com.google.code.findbugs:jsr305:3.0.2"
                ],
                "directDependencies": [
                    "com.google.code.findbugs:jsr305:3.0.2"
                ],
                "file": "v1/https/repo1.maven.org/guava.jar",
                "sha256": "bbbb",
                "url": "https://repo1.maven.org/maven2/guava.jar"
            },
            {
                "coord": "com.google.code.findbugs:jsr305:3.0.2",
                "dependencies": [],
                "directDependencies": [],
                "file": "v1/https/repo1.maven.org/jsr305.jar",
                "sha256": "cccc",
                "url": "https://repo1.maven.org/maven2/jsr305.jar"
            }
        ],
        "version": "0.1.0"
    }
}`

const installJSONAfter = `{
    "dependency_tree": {
        "dependencies": [
            {
                "coord": "com.acme:auth-client:2.1.0",
                "directDependencies": [
                    "com.google.guava:guava:32.0.0-jre"
                ]
            },
            {
                "coord": "com.google.guava:guava:32.0.0-jre",
                "directDependencies": [
                    "com.google.code.findbugs:jsr305:3.0.2"
                ]
            },
            {
                "coord": "com.google.code.findbugs:jsr305:3.0.2",
                "directDependencies": []
            }
        ]
    }
}
`

func TestSanitizeInstallJSON(t *testing.T) {
	sanitized, err := sanitizeInstallJSON([]byte(installJSONBefore), nil)

	assert.NoError(t, err)
	assert.Equal(t, installJSONAfter, string(sanitized))
	assert.NotContains(t, string(sanitized), "acme.internal")
}

func TestSanitizeInstallJSONUsesDependenciesWhenThereAreNoDirectOnes(t *testing.T) {
	before := `{"dependency_tree": {"dependencies": [
		{"coord": "a:b:1", "dependencies": ["c:d:2"], "url": "https://ci:s3cret@repo.acme.internal/b.jar"},
		{"coord": "c:d:2"}
	]}}`

	sanitized, err := sanitizeInstallJSON([]byte(before), nil)

	assert.NoError(t, err)
	assert.Equal(t, `{
    "dependency_tree": {
        "dependencies": [
            {
                "coord": "a:b:1",
                "dependencies": [
                    "c:d:2"
                ]
            },
            {
                "coord": "c:d:2"
            }
        ]
    }
}
`, string(sanitized))
}

func TestSanitizeInstallJSONInvalid(t *testing.T) {
	for _, content := range []string{
		``,
		`[]`,
		`{"version": "2", "artifacts": {}}`,
		`{"dependency_tree": []}`,
		`{"dependency_tree": {"dependencies": {}}}`,
		`{"dependency_tree": {"dependencies": ["a:b:1"]}}`,
		`{"dependency_tree": {"dependencies": [{"url": "https://repo/b.jar"}]}}`,
		`{"dependency_tree": {"dependencies": [{"coord": "a:b:1", "directDependencies": "c:d:2"}]}}`,
		`{"dependency_tree": {"dependencies": [{"coord": "a:b:1", "directDependencies": [{"coord": "c:d:2"}]}]}}`,
	} {
		_, err := sanitizeInstallJSON([]byte(content), nil)
		assert.ErrorIs(t, err, util.ErrInvalidFormat, content)
	}
}
